import{a as t}from"./chunks/theme.Bko_wsX5.js";import{_ as a,a as o,c as s,k as n}from"./chunks/framework.CfBWHN5N.js";const m=JSON.parse('{"title":"Teaching AI","description":"Explore three NJIT classroom Studios and download a starter for designing AI-assisted assignments where students make and check their own decisions.","frontmatter":{"title":"Teaching AI","description":"Explore three NJIT classroom Studios and download a starter for designing AI-assisted assignments where students make and check their own decisions.","teaser":"Give the AI coach one job. Leave the student one decision worth making. Three classroom Studios show what that looks like in practice."},"headers":[],"relativePath":"teaching.md","filePath":"teaching.md"}'),r={name:"teaching.md"};function i(h,e,d,c,l,u){return o(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="teaching-ai" tabindex="-1">Teaching AI <a class="header-anchor" href="#teaching-ai" aria-label="Permalink to &quot;Teaching AI&quot;">​</a></h1><p>After more than two decades at NJIT, I still look forward to handing a student’s work to someone who has never seen it. A classmate trying to buy a T-shirt can find a problem that everyone who built the store missed. The student gets feedback they can use straight away. As their teacher, I get to see how they decide what to change.</p><h2 id="the-tests-passed-who-won-the-game" tabindex="-1">The Tests Passed. Who Won the Game? <a class="header-anchor" href="#the-tests-passed-who-won-the-game" aria-label="Permalink to &quot;The Tests Passed. Who Won the Game?&quot;">​</a></h2><p>My web applications starter passed twelve automated checks and still couldn’t settle a round of rock-paper-scissors. That was deliberate. The part I wanted the student to explain was what happens when the computer picks paper and the player picks rock. The feature follows that question through three courses. <a href="/teaching/when-ai-helps-write-the-code">Read the classroom story</a></p><p><img src="'+t+'" alt="A learner holds a pencil over a blank card beside a worked example."></p><h2 id="build-something-you-can-explain" tabindex="-1">Build something you can explain <a class="header-anchor" href="#build-something-you-can-explain" aria-label="Permalink to &quot;Build something you can explain&quot;">​</a></h2><p>I call these activities <em>Studios</em>. Students try a starter, choose one change, build it with help, and check what actually happened. A plain-text file called <code>AGENTS.md</code> tells the AI assistant when to help, what to ask, and when to wait.</p><table tabindex="0"><thead><tr><th>Studio</th><th>A decision the student makes</th></tr></thead><tbody><tr><td><a href="https://github.com/kaw393939/is117-brand-studio" target="_blank" rel="noreferrer">Brand Studio · Intro to Website Development</a></td><td>Choose the audience for a plain white T-shirt. Point to one design or wording choice that fits that buyer.</td></tr><tr><td><a href="https://github.com/kaw393939/is218-rps-starter" target="_blank" rel="noreferrer">Rock, Paper, Scissors · Building Web Applications</a></td><td>Predict the outcome of a round from the player’s point of view. Check a test, then play it yourself.</td></tr><tr><td><a href="https://github.com/kaw393939/373_hosting" target="_blank" rel="noreferrer">Server Studio · Content Management Systems</a></td><td>Predict how a request will reach a calculator running on your server. Open the public address and see what happens.</td></tr></tbody></table><p>For a project that works with documents, try the <a href="/knowledge-lab/">Knowledge Lab</a>. Give the system a question it can answer and ask for the passage that supports its answer. Then ask for a detail the collection leaves out.</p><h2 id="try-a-studio-in-your-course" tabindex="-1">Try a Studio in your course <a class="header-anchor" href="#try-a-studio-in-your-course" aria-label="Permalink to &quot;Try a Studio in your course&quot;">​</a></h2><p>Pick an assignment you already teach and a decision you want students to make. Rehearse the assignment once, playing a student who is stuck. Does the coach give a helpful hint, or does it make the decision for you?</p><p>The download includes a worked example, a student handout, and the coach’s instructions. <strong>The teacher copy contains answers. Share only <code>LESSON.md</code> and <code>AGENTS.md</code> with students.</strong> <a href="/downloads/AI-Studio-Starter.zip">Download the teacher Studio starter</a> · <a href="/teaching/studio-field-notes">Read the research behind the starter</a></p><h2 id="learning-beyond-one-assignment" tabindex="-1">Learning beyond one assignment <a class="header-anchor" href="#learning-beyond-one-assignment" aria-label="Permalink to &quot;Learning beyond one assignment&quot;">​</a></h2><p>I’m investigating which decisions students can make when the next task looks different. The <a href="/research">research agenda</a> explains the question. Students choosing a portfolio project can use the <a href="/ai-careers">AI career field guide</a> to find a responsibility they want to practice.</p><p>I publish two tools for people designing their own materials. The Educational Design System provides reusable layouts for course sites. Everyday AI CLI is an alpha command-line toolkit for repeatable AI tasks. <a href="https://kaw393939.github.io/educational-design-system/" target="_blank" rel="noreferrer">Explore the Educational Design System</a> · <a href="https://github.com/kaw393939/everyday-ai-cli" target="_blank" rel="noreferrer">See Everyday AI CLI</a></p>',15)])])}const w=a(r,[["render",i]]);export{m as __pageData,w as default};
